// Generated by scripts/herdr-icons: do not edit by hand.
// Program icons cropped to their artwork, so each fills its slot to the same size,
// and Claude Code and Codex as clean one-colour marks.
const DIR = "mods/agent-list/icons";
const OWN = { claude: "#D97757", codex: "#6F7DFF" };
const CROPPED = new Set(["agent", "amp", "ansible", "antigravity", "apt", "astro", "biome", "brew", "bun", "caddy", "cargo", "cmake", "command-code", "composer", "copilot", "crush", "curl", "cursor", "dart", "deno", "django-admin", "dnf", "docker", "dotnet", "dsh-tui", "electron", "emacs", "erl", "esbuild", "eslint", "expo", "fastapi", "ffmpeg", "flask", "flutter", "fly", "gcloud", "gemini", "gh", "ghci", "git", "glab", "go", "goose", "gradle", "grok", "helm", "hermes", "htop", "hx", "iex", "java", "jest", "julia", "jupyter", "kimi", "kiro", "kotlin", "kubectl", "lazygit", "less", "lua", "make", "mastracode", "mongosh", "muse", "mvn", "mysql", "nano", "netlify", "next", "nginx", "nix", "node", "npm", "nuxt", "nvim", "ocaml", "ollama", "omp", "opencode", "pacman", "perl", "php", "pi", "pig", "pnpm", "podman", "poetry", "prettier", "prime-agent", "prisma", "program", "psql", "pytest", "python", "qoder", "r", "redis-cli", "rg", "ruby", "ruff", "scala", "shell", "sqlite3", "ssh", "supabase", "swift", "tauri", "terraform", "tmux", "tsc", "turbo", "uv", "vercel", "vim", "vite", "vitest", "webpack", "wrangler", "yarn", "zig"]);

// How to draw a program's icon: { path, tint, color }. tint draws it as a mask
// in color (or the caller's colour when color is null); otherwise as an image.
export function programIcon(p) {
  if (!p) return null;
  if (OWN[p.key]) return { path: `${DIR}/${p.key}.svg`, tint: true, color: OWN[p.key] };
  if (!p.icon) return null;
  const name = p.icon.replace(/^icons\//, "").replace(/\.svg$/, "");
  const path = CROPPED.has(name) ? `${DIR}/programs/${name}.svg` : p.icon;
  return { path, tint: Boolean(p.tint), color: null };
}
